INSERT INTO "salient_features" VALUES(1,1,'Procurement','1. अधिप्राप्ति- दिनांक 30.06.2026 तक खरीफ विपणन मौसम 2025-26 में धान ( चावल के तुल्य ) की खरीद 557.28 लाख मीट्रिक टन हो चुकी है। जबकि पिछले विपणन मौसम (खरीफ विपणन मौसम 2024-25) तदनुरूप अवधि के दौरान अधिप्राप्ति 530.78 लाख मीट्रिक टन थी। खरीफ विपणन मौसम 2024-25 में धान ( चावल के तुल्य ) की अधिप्राप्ति 552.98 लाख मीट्रिक टन है, जहां तक गेहूं का संबंध है, रबी विपणन मौसम 2026-27 में  357.57 लाख टन की अधिप्राप्ति की गयी है, जबकि पिछले विपणन मौसम (रबी विपणन मौसम 2025-26) के दौरान 300.35 लाख मीट्रिक टन गेंहू की अधिप्राप्ति की गयी थी ।',NULL);
INSERT INTO "salient_features" VALUES(2,1,'Procurement',NULL,'1. Procurement- Upto 30.06.2026, Procurement of paddy (in terms of rice) during KMS 2025-26 is 557.28 LMT whereas procurement in the previous marketing season (KMS 2024-25) during corresponding period was 530.78 LMT. Procurement of paddy (in terms of rice) during KMS 2024-25 is 552.98 LMT .As far as wheat is concerned, in RMS 2026-27, a quantity of 357.57 LMT of wheat has been procured whereas procurement in the previous marketing season (RMS 2025-26) was 300.35 LMT.');
INSERT INTO "salient_features" VALUES(3,2,'Stock','2. स्टॉक– दिनांक 30.06.2026 (समापन स्टॉक ) की स्थिति के अनुसार भारतीय खाद्य निगम तथा राज्य एजेंसियों के पास उपलब्‍ध चावल और गेहूं का कुल स्टॉक 925.85 लाख टन था जिसमें 403.11 लाख टन चावल तथा 522.74 लाख टन गेहूं शामिल है।',NULL);
INSERT INTO "salient_features" VALUES(4,2,'Stock',NULL,'2. Stock -The total stocks of rice and wheat held by FCI and State agencies as on 30.06.2026 (closing Stock) was 925.85 lakh tonnes comprising 403.11 lakh tonnes of rice and 522.74 lakh tonnes of wheat.');
INSERT INTO "salient_features" VALUES(5,3,'Offtake','3. उठान – माह मई, 2026 के दौरान सभी स्कीमों के अंतर्गत चावल का उठान 38.64 लाख टन था। इसमें राष्ट्रीय खाद्य सुरक्षा कानून के अंतर्गत 26.41 लाख टन का उठान जून, 2026 माह के आवंटन के सापेक्ष है तथा अन्य स्कीमों के अंतर्गत 12.23 लाख टन का उठान शामिल है। जहां तक गेहूं का संबंध है, कुल उठान 16.31 लाख टन था जिसमें राष्ट्रीय खाद्य सुरक्षा कानून के अंतर्गत 14.98 लाख टन का उठान (जून, 2026 माह के आवंटन के सापेक्ष)  है तथा अन्यस्कीमों के अंतर्गत 1.33 लाख टन उठान शामिल है।',NULL);
INSERT INTO "salient_features" VALUES(6,3,'Offtake',NULL,'3. Offtake – The offtake of rice under the all schemes during the month of May, 2026 has been 38.64 lakh tonnes. This comprises 26.41 lakh tonnes under NFSA (offtake against the allocation for the month of June, 2026) and 12.23 lakh tonnes under other schemes. In respect of wheat, the total offtake has been 16.31 lakh tones comprising 14.98 lakh tonnes under NFSA (offtake against the allocation for the month of June, 2026) and 1.33 lakh tonnes under other schemes.');
INSERT INTO "salient_features" VALUES(7,3,'Offtake','4. वर्ष 2026-27 के दौरान June, 2026 माह में खाद्यान्न के आबंटन के सापेक्ष एनएफएसए के अंतर्गत उठान की प्रवृत्ति
INSERT INTO "salient_features" VALUES(8,3,'Offtake','(मात्रा लाख टन में) (In lakh tons)',NULL);
